using UnityEngine;using System.Linq;
public static class InspectRackVertices {public static string Main(){var b=Object.FindObjectsByType<BicycleController>(FindObjectsSortMode.None).First(b=>!b.motorDriven);var f=b.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="Frame");var v=f.sharedMesh.vertices.Select(p=>b.transform.InverseTransformPoint(f.transform.TransformPoint(p))).Where(p=>p.z<-.35f&&p.y>.15f).ToArray();var bounds=new Bounds(v[0],Vector3.zero);foreach(var p in v)bounds.Encapsulate(p);return bounds.ToString()+" highest="+string.Join(";",v.OrderByDescending(p=>p.y).Take(8))+" bikepos="+b.transform.position;}}
